const express = require('express');
const crypto = require('crypto');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// Session store with revocation support
class SessionStore {
  constructor() {
    this.sessions = new Map();
    this.revocationCounter = new Map(); // userId -> counter of revoked sessions
    this.MAX_SESSIONS_PER_USER = 5;
  }

  createSession(userId, role) {
    const sessionId = crypto.randomBytes(16).toString('hex');
    const counter = this.getNextCounter(userId);
    const session = {
      id: sessionId,
      userId,
      role,
      counter,
      createdAt: Date.now(),
      expiresAt: Date.now() + 3600000
    };
    this.sessions.set(sessionId, session);
    return session;
  }

  getNextCounter(userId) {
    const current = this.revocationCounter.get(userId) || 0;
    // Use 16-bit counter space to save memory in session tokens
    const next = (current + 1) & 0xFFFF;
    this.revocationCounter.set(userId, next);
    return next;
  }

  revokeAllSessions(userId) {
    // Revoke by advancing the counter - sessions with counter <= revocation point are invalid
    const currentCounter = this.revocationCounter.get(userId) || 0;
    // Store the revocation point
    this.sessions.forEach((session, id) => {
      if (session.userId === userId) {
        this.sessions.delete(id);
      }
    });
    // The revocation counter stays at currentCounter
    // New sessions will get counter > currentCounter
    return currentCounter;
  }

  getSession(sessionId) {
    return this.sessions.get(sessionId) || null;
  }
}

// Token encoding: userId.counter.hmac
class TokenService {
  constructor(secret) {
    this.secret = secret;
  }

  encode(session) {
    const payload = `${session.userId}:${session.id}:${session.counter}:${session.expiresAt}`;
    const hmac = crypto.createHmac('sha256', this.secret)
      .update(payload)
      .digest('hex');
    return Buffer.from(`${payload}:${hmac}`).toString('base64url');
  }

  decode(token) {
    try {
      const decoded = Buffer.from(token, 'base64url').toString();
      const parts = decoded.split(':');
      if (parts.length !== 5) return null;
      const [userId, sessionId, counterStr, expiresAtStr, hmac] = parts;
      const payload = `${userId}:${sessionId}:${counterStr}:${expiresAtStr}`;
      const expectedHmac = crypto.createHmac('sha256', this.secret)
        .update(payload)
        .digest('hex');
      if (!crypto.timingSafeEqual(Buffer.from(hmac), Buffer.from(expectedHmac))) {
        return null;
      }
      return {
        userId,
        sessionId,
        counter: parseInt(counterStr, 10),
        expiresAt: parseInt(expiresAtStr, 10)
      };
    } catch {
      return null;
    }
  }
}

// Revocation validation service
class RevocationService {
  constructor(sessionStore) {
    this.store = sessionStore;
    this.revocationPoints = new Map(); // userId -> revocation counter point
  }

  recordRevocation(userId) {
    const point = this.store.revokeAllSessions(userId);
    this.revocationPoints.set(userId, point);
    return point;
  }

  isRevoked(userId, sessionCounter) {
    const revocationPoint = this.revocationPoints.get(userId);
    if (revocationPoint === undefined) return false;
    // Session is valid if its counter is AFTER the revocation point
    // Using unsigned 16-bit arithmetic for counter comparison
    const distance = (sessionCounter - revocationPoint) & 0xFFFF;
    // If distance is in the "forward" half of the counter space, session is newer
    return distance === 0 || distance > 0x7FFF;
  }
}

const sessionStore = new SessionStore();
const tokenService = new TokenService(crypto.randomBytes(32));
const revocationService = new RevocationService(sessionStore);

// Simulated user database
const users = new Map();

async function initUsers() {
  users.set('admin', {
    id: 'admin',
    passwordHash: await argon2.hash('admin_password_123'),
    role: 'admin'
  });
  users.set('user1', {
    id: 'user1',
    passwordHash: await argon2.hash('user_password_456'),
    role: 'user'
  });
}

app.post('/auth/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing credentials' });
  const user = users.get(username);
  if (!user) return res.status(401).json({ error: 'Invalid credentials' });
  try {
    if (!await argon2.verify(user.passwordHash, password)) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }
  } catch {
    return res.status(500).json({ error: 'Internal error' });
  }
  const session = sessionStore.createSession(user.id, user.role);
  const token = tokenService.encode(session);
  res.json({ token, expiresAt: session.expiresAt });
});

app.post('/auth/revoke-all', (req, res) => {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  const decoded = tokenService.decode(token);
  if (!decoded) return res.status(401).json({ error: 'Invalid token' });
  revocationService.recordRevocation(decoded.userId);
  res.json({ message: 'All sessions revoked' });
});

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');
  if (!token) return res.status(401).json({ error: 'No token' });
  const decoded = tokenService.decode(token);
  if (!decoded) return res.status(401).json({ error: 'Invalid token' });
  if (decoded.expiresAt < Date.now()) {
    return res.status(401).json({ error: 'Token expired' });
  }
  // Check revocation using counter comparison
  if (revocationService.isRevoked(decoded.userId, decoded.counter)) {
    return res.status(401).json({ error: 'Session revoked' });
  }
  req.user = { id: decoded.userId, sessionId: decoded.sessionId };
  next();
}

app.get('/api/profile', authMiddleware, (req, res) => {
  const user = users.get(req.user.id);
  if (!user) return res.status(404).json({ error: 'User not found' });
  res.json({ id: user.id, role: user.role });
});

app.get('/api/admin', authMiddleware, (req, res) => {
  const user = users.get(req.user.id);
  if (!user || user.role !== 'admin') return res.status(403).json({ error: 'Forbidden' });
  res.json({ secrets: 'admin-only-data', users: Array.from(users.keys()) });
});

initUsers().then(() => app.listen(3000));

module.exports = { app, sessionStore, tokenService, revocationService, SessionStore, TokenService, RevocationService };
